<!-- src/views/Login.vue -->
<template>
  <v-container>
    <v-form @submit.prevent="handleLogin" ref="form">
      <v-text-field
        label="Username"
        v-model="username"
        required
      ></v-text-field>
      <v-text-field
        label="Password"
        type="password"
        v-model="password"
        required
      ></v-text-field>
      <v-btn type="submit" color="primary">Login</v-btn>
    </v-form>
    <p>Auth State: {{ authStore.isAuthenticated }}</p>
    <p v-if="loginError" style="color: red;">Login Error: {{ loginError }}</p>
  </v-container>
</template>

<script>
import { useAuthStore } from '@/stores/authStore';
import { useRouter } from 'vue-router';

export default {
  name: 'LogIn',
  setup() {
    const authStore = useAuthStore();
    const router = useRouter();
    console.log('Login.vue: Initial isAuthenticated:', authStore.isAuthenticated);
    return { authStore, router };
  },
  data() {
    return {
      username: '',
      password: '',
      loginError: null,
    };
  },
  methods: {
    async handleLogin() {
      console.log('handleLogin called with:', this.username, this.password);
      try {
        await this.authStore.login();
        console.log('After login, isAuthenticated:', this.authStore.isAuthenticated);
        this.router.push('/listByProject');
      } catch (error) {
        console.error('Login error:', error);
        this.loginError = error.message || 'Failed to login';
      }
    },
  },
};
</script>